import Foundation

/// The open source code that ships in the app, with the license texts we
/// must pass on. Generated by scripts/generate_licenses.py.
nonisolated struct OpenSourceLicenses: Decodable, Sendable {
    struct Package: Decodable, Identifiable, Sendable {
        let name: String
        let version: String
        let license: String
        let url: URL
        let note: String?
        let texts: [String]

        var id: String { "\(name) \(version)" }
    }

    /// The Swift package revisions the list was generated from.
    let sources: [String: String]
    let packages: [Package]
    /// License texts, stored once and shared by the packages that use them.
    let texts: [String: String]

    static let bundled: OpenSourceLicenses? = {
        let licenses = Bundle.main
            .url(forResource: "OpenSourceLicenses", withExtension: "json")
            .flatMap { try? Data(contentsOf: $0) }
            .flatMap { try? JSONDecoder().decode(OpenSourceLicenses.self, from: $0) }
        assert(licenses != nil, "OpenSourceLicenses.json is missing from the app bundle")
        return licenses
    }()

    func texts(for package: Package) -> [String] {
        package.texts.compactMap { texts[$0] }
    }

    /// Joins hard-wrapped lines so the text fits any width. Blank lines
    /// still separate paragraphs, and list items like `2.` or `(a)` start
    /// their own line.
    static func reflowed(_ text: String) -> String {
        let listItem = /(\d+\.|\([a-z0-9]+\)|[-*•])\s/
        return text.split(omittingEmptySubsequences: false, whereSeparator: \.isNewline)
            .split(whereSeparator: {
                $0.trimmingCharacters(in: .whitespaces).isEmpty
            })
            .map { lines in
                lines.map { $0.trimmingCharacters(in: .whitespaces) }
                    .reduce(into: "") { paragraph, line in
                        if !paragraph.isEmpty {
                            paragraph += line.starts(with: listItem) ? "\n" : " "
                        }
                        paragraph += line
                    }
            }
            .joined(separator: "\n\n")
    }
}
